UPDATE news
title = #{title}, content = #{content}, media_type = #{mediaType}, update_time = NOW()
WHERE id = #{id}

UPDATE news
SET like_count = COALESCE(like_count, 0) + #{delta}, update_time = NOW()
WHERE id = #{id}

UPDATE news
SET collect_count = COALESCE(collect_count, 0) + #{delta}, update_time = NOW()
WHERE id = #{id}

UPDATE news
SET comment_count = COALESCE(comment_count, 0) + #{delta}, update_time = NOW()
WHERE id = #{id}
